package com.smartmanager.nativeapp;
import java.util.*;
/** Reads stable identity from RouterOS; serial is required for automatic reconciliation. */
public final class RouterIdentityResolver { private RouterIdentityResolver(){} public static String resolve(RouterService r)throws Exception{List<Map<String,String>> resource=r.execute("/system/resource/print","=.proplist=board-name,architecture-name,version");if(resource.isEmpty())throw new java.io.IOException("تعذر قراءة معلومات الراوتر");Map<String,String> x=resource.get(0);String serial="";try{List<Map<String,String>> rb=r.execute("/system/routerboard/print","=.proplist=serial-number,board-name");if(!rb.isEmpty())serial=rb.get(0).getOrDefault("serial-number","");}catch(java.io.IOException denied){throw new java.io.IOException("لا يمكن قراءة الرقم التسلسلي أو لا توجد صلاحية");}if(serial.trim().isEmpty())throw new java.io.IOException("الراوتر لا يوفر رقمًا تسلسليًا موثوقًا");return RouterIdentity.device(x.get("board-name"),x.get("architecture-name"),serial,x.get("version"));} }
